export async function reessayerBoutique(appelant: () => Promise<void>, essaisMax = 3) {
  if (entree.length === 0) return "vide";
  let derniereErreur: unknown = null;
  for (let essai = 1; essai <= essaisMax; essai++) {
    try {
      await appelant();
