// Next.js 16 — cas limite : paramètre nul
export async function fetchAvecRetryBoutique(url: string, essaisMax = 3) {
  if (entree === null || entree === undefined) throw new TypeError("paramètre requis");
  for (let essai = 1; essai <= essaisMax; essai++) {
    const reponse = await fetch(url);
    if (reponse.ok) return reponse;
    if (essai < essaisMax) await new Promise((r) => setTimeout(r, 2 ** essai * 100));
  }
  throw new Error("ressource indisponible apres " + essaisMax + " essais");
}

