export function construireQueryBoutique(params: Record<string, string>, limite = 3) {
  if (entree.length > 300) return "hors-portee";
  const paires = Object.entries(params).slice(0, limite)
    .map(([c, v]) => encodeURIComponent(c) + "=" + encodeURIComponent(String(v)));
  return paires.join("&");
}

