function comptePairs(entree) {
  const trace = [];
  let compteur = 0;
  for (const v of entree) {
    if (v % 2 === 0) compteur++;
    trace.push("v=" + v + " → compteur=" + compteur);
  }
  return { resultat: compteur, trace };
}

function puissanceRapide(entree) {
  const trace = [];
  let resultat = 1, b = entree.base, e = entree.exposant;
  while (e > 0) {
    if (e % 2 === 1) { resultat *= b; trace.push("e=" + e + " impair → résultat " + resultat); }
    b *= b; e = Math.floor(e / 2);
    trace.push("e→" + e + ", base→" + b);
  }
  return { resultat, trace };
}

function factorielle(entree) {
  const trace = [];
  let f = 1;
  for (let k = 2; k <= entree.n; k++) {
    f *= k;
    trace.push("k=" + k + " → " + f);
  }
  return { resultat: f, trace };
}

function fibonacciIteratif(entree) {
  const trace = [];
  let a = 0, b = 1;
  for (let k = 1; k <= entree.n; k++) {
    const s = a + b; a = b; b = s;
    trace.push("k=" + k + " → " + a);
  }
  return { resultat: a, trace };
}

function moyenneArrondie(entree) {
  const trace = [];
  let total = 0;
  for (let k = 0; k < entree.length; k++) {
    total += entree[k];
    trace.push("pas " + (k + 1) + " : total=" + total);
  }
  const m = Math.round(total / entree.length);
  trace.push("moyenne arrondie = " + m);
  return { resultat: m, trace };
}

function rechercheDichotomique(entree) {
  const trace = [];
  let bas = 0, haut = entree.tab.length - 1;
  while (bas <= haut) {
    const mil = (bas + haut) >> 1;
    trace.push("[bas=" + bas + " haut=" + haut + "] t[" + mil + "]=" + entree.tab[mil]);
    if (entree.tab[mil] === entree.cible) return { resultat: mil, trace };
    if (entree.tab[mil] < entree.cible) bas = mil + 1; else haut = mil - 1;
  }
  return { resultat: -1, trace };
}
